(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.018+t*0.4)*20 + Math.cos(y*0.012-t*0.3)*15 + Math.sin((x+y)*0.008+t*0.15)*10;
  const wy = Math.cos(y*0.018-t*0.35)*20 + Math.sin(x*0.015+t*0.45)*15 + Math.cos((x-y)*0.01-t*0.2)*10;
  const sx = x + wx, sy = y + wy;
  const wells = [
    [140+Math.sin(t*0.3)*80, 70+Math.cos(t*0.25)*40, 3.2, 0.07, 0],
    [340+Math.cos(t*0.35)*90, 170+Math.sin(t*0.4)*50, 2.8, 0.08, 2.1],
    [240+Math.sin(t*0.2+1.5)*120, 120+Math.cos(t*0.3+1)*80, 3.5, 0.055, 4.2],
    [80+Math.cos(t*0.45+3)*60, 190+Math.sin(t*0.35+2)*45, 2.2, 0.1, 1.0],
    [400+Math.sin(t*0.28+4)*70, 50+Math.cos(t*0.5+3)*55, 2.6, 0.075, 3.1],
    [200+Math.cos(t*0.32+5)*100, 210+Math.sin(t*0.38)*65, 3.0, 0.065, 5.3],
    [300+Math.sin(t*0.42+2)*85, 100+Math.cos(t*0.33+4)*70, 2.4, 0.09, 0.7]
  ];
  let potential = 0, kinetic = 0, flow = 0;
  for (let i = 0; i < wells.length; i++) {
    const [gX, gY, mass, freq, phase] = wells[i];
    const dx = sx - gX, dy = sy - gY;
    const dist = Math.sqrt(dx*dx + dy*dy) + 1;
    potential -= mass * 50 / dist;
    const orbV = mass * 15 / dist;
    const ang = Math.atan2(dy, dx);
    kinetic += Math.sin(dist*freq - t*orbV*0.15 + phase) * orbV * 0.3;
    flow += Math.cos(ang*2 + t*0.5 + phase) * Math.sin(dist*0.04 - t*0.8) * mass * 0.1;
  }
  const distC = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const angC = Math.atan2(sy-cy, sx-cx);
  const spiral = Math.sin(distC*0.04 - angC*4 - t*1.8) * Math.cos(distC*0.03 + angC*3 + t*1.2) * (180/(distC+40));
  const turbulence = (Math.sin(sx*0.035+sy*0.025+t*1.2) + Math.sin(sx*0.025-sy*0.04+t*1.5) + Math.sin((sx+sy)*0.015+t*0.9))/3;
  const totalEnergy = potential + kinetic*0.6 + spiral*40 + flow*30 + turbulence*20;
  const activated = Math.tanh(totalEnergy * 0.025);
  const inhibited = Math.tanh((kinetic*0.4 - potential*0.3 + flow*20 + turbulence*15) * 0.02);
  const rd = Math.tanh((activated - inhibited*0.8 + spiral*0.3) * 3.0);
  const detail = Math.sin(sx*0.12+t*0.7)*Math.sin(sy*0.12-t*0.5)*0.15 + Math.sin((sx-sy)*0.08+t*1.3)*0.1;
  const blend = rd*0.8 + detail*0.2;
  const v = blend*0.5+0.5;
  const neon = [
    [0,0,0],[5,0,20],[10,0,60],[20,5,120],[40,0,200],[80,0,255],
    [0,80,255],[0,180,255],[0,255,200],[50,255,100],[180,255,0],
    [255,200,0],[255,100,0],[255,20,50],[255,0,120],[200,0,180],
    [120,0,200],[60,0,140],[20,0,60],[0,0,0]
  ];
  const idx = v*(neon.length-1), i = Math.min(idx|0, neon.length-2), f = idx-i;
  const edgeGlow = Math.abs(rd) > 0.65 ? 1.0 + (Math.abs(rd)-0.65)*3.0 : 1.0;
  const hotSpot = Math.max(0, rd - 0.5)*2.0;
  return [
    Math.min(255, ((neon[i][0]+(neon[i+1][0]-neon[i][0])*f)*edgeGlow + hotSpot*80)|0),
    Math.min(255, ((neon[i][1]+(neon[i+1][1]-neon[i][1])*f)*edgeGlow + hotSpot*60)|0),
    Math.min(255, ((neon[i][2]+(neon[i+1][2]-neon[i][2])*f)*edgeGlow + hotSpot*100)|0)
  ];
}
